import { existsSync, readdirSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import type { HarnessName, ResolvedHarness } from "./types.ts";

export interface UpstreamMap {
	path: string;
	symbol?: string;
	sections?: string[];
	note?: string;
}

export interface ProfileSource {
	overlay?: string | null;
	upstream: UpstreamMap[];
}

export interface HarnessSource {
	family: string;
	ref: {
		path: string;
		remote?: string;
		rev: string;
	};
	watch?: string[];
	shared?: string | null;
	profiles: Record<string, ProfileSource>;
	dir: string;
}

let cached: HarnessSource[] | undefined;

export function defaultSourcesRoot(): string {
	return join(dirname(fileURLToPath(import.meta.url)), "sources");
}

export function loadHarnessSources(root = defaultSourcesRoot()): HarnessSource[] {
	if (!existsSync(root)) return [];
	const out: HarnessSource[] = [];
	for (const name of readdirSync(root)) {
		const dir = join(root, name);
		const file = join(dir, "SOURCE.json");
		if (!existsSync(file)) continue;
		const parsed = JSON.parse(readFileSync(file, "utf8")) as Omit<HarnessSource, "dir">;
		out.push({ ...parsed, dir });
	}
	return out;
}

function sources(root?: string): HarnessSource[] {
	if (root) return loadHarnessSources(root);
	cached ??= loadHarnessSources();
	return cached;
}

function readOptional(dir: string, rel: string | null | undefined): string {
	if (!rel) return "";
	const path = join(dir, rel);
	if (!existsSync(path)) {
		throw new Error(`Missing overlay file: ${path}`);
	}
	return readFileSync(path, "utf8").trim();
}

export function familySharedBody(family: string, root?: string): string {
	for (const source of sources(root)) {
		if (source.family !== family) continue;
		return readOptional(source.dir, source.shared);
	}
	return "";
}

export function overlayBody(name: HarnessName, root?: string): string {
	for (const source of sources(root)) {
		const profile = source.profiles[name];
		if (!profile) continue;
		const parts = [readOptional(source.dir, source.shared), readOptional(source.dir, profile.overlay)];
		return parts.filter(Boolean).join("\n");
	}
	throw new Error(`No overlay source for harness ${name}`);
}

export function renderOverlay(resolved: ResolvedHarness, root?: string): string {
	return `<harness>
${overlayBody(resolved.name, root)}
</harness>`;
}

